"""国語：文法（言葉の単位・文の成分／単語のいろいろ・日本語の音声・方言）。例文はすべて Claude が作ったもの"""
from koku import unit, T, C, SEQ, N, S, R

MAJ = '文法'

def bunpo1():
    u = unit('bunpo1', '言葉の単位と文の成分', MAJ, {14, 15, 16, 17, 48, 49, 50, 51},
             '2026-10-07 Claude作成。国語ワークp14〜15（文法1 言葉の単位）、p16〜17（単語・複合語）、p48〜51（文法2 文の成分）を写真で確認し、例文をすべて新しく作った。手書きの答えは使っていない。')
    q = u.q
    q(14, '文法1', '言葉の単位', '言葉の単位を、大きいものから順に並べよう（記号で）。\nア 文　イ 単語　ウ 文章（談話）　エ 段落　オ 文節', SEQ(['ウ', 'エ', 'ア', 'オ', 'イ']), '文章（談話）＞段落＞文＞文節＞単語。', near=['ウアエオイ', 'ウエアイオ'])
    q(14, '文法1', '言葉の単位', '文章の中で、内容のまとまりごとに区切ったものを何というか。', T('段落', 'だんらく'), '段落。変わり目は行を改め、一字分下げて書く。', near=['文', '文節'])
    q(14, '文法1', '言葉の単位', '新しい段落を書き始めるとき、書き出しはどうするか。', R((1, ['一字', '1字', '一ます', '1ます', '一マス', '1マス']), (1, ['下げ', 'あけ', '空け'])), '行を改め、書き出しを一字分下げる。', example='行を改めて、一字分下げて書き始める。')
    q(14, '文法1', '言葉の単位', '文の終わりに付ける記号は何か。', T('句点', '。', 'くてん', '句点（。）'), '文は句点「。」で終わる。', near=['読点', '、'])
    q(14, '文法1', '文節', '意味がわかる範囲で、発音が不自然にならないように文をできるだけ短く区切ったまとまりを何というか。', T('文節', 'ぶんせつ'), '文節。「ネ」「サ」を入れて区切れる所が切れ目。', near=['単語', '段落'])
    q(14, '文法1', '文節', '文を文節に区切るとき、区切れ目を確かめるために入れてみるとよい言葉を、カタカナ1字で答えよう。', T('ネ', 'サ', 'ヨ'), '「ネ」「サ」「ヨ」を入れて自然なら文節の切れ目。', near=['ノ'])
    for sent, n, nr, expl in [('姉は毎朝公園を走る。', 4, ['5', '3'], '姉は／毎朝／公園を／走る（4文節）。'),
                              ('小さな犬がうれしそうにしっぽを振った。', 5, ['6', '4'], '小さな／犬が／うれしそうに／しっぽを／振った（5文節）。'),
                              ('ぼくは図書館で本を三冊借りた。', 5, ['6', '4'], 'ぼくは／図書館で／本を／三冊／借りた（5文節）。'),
                              ('雨が降ってきたので、急いで家に帰った。', 6, ['5', '7'], '雨が／降って／きたので／急いで／家に／帰った（6文節）。「降ってきた」は「降って／きた」と二つの文節に分かれる。'),
                              ('となりの町まで自転車で行ってみる。', 5, ['4', '6'], 'となりの／町まで／自転車で／行って／みる（5文節）。'),
                              ('先生、この問題の答えを教えてください。', 6, ['5', '7'], '先生、／この／問題の／答えを／教えて／ください（6文節）。')]:
        q(14, '文法1', '文節の数', f'次の文はいくつの文節に分けられるか。\n{sent}', N(n, ['文節', 'つ']), expl, near=nr)
    q(14, '文法1', '文節に区切る', '次の文を文節に区切り、「／」を使って書こう。\n弟は庭で花を育てる。', T('弟は／庭で／花を／育てる。', '弟は/庭で/花を/育てる', '弟は／庭で／花を／育てる', '弟は|庭で|花を|育てる'), '弟は（ネ）庭で（ネ）花を（ネ）育てる。', near=['弟／は／庭／で／花／を／育てる。', '弟は庭で／花を育てる。'])
    q(16, '文法1', '単語', '文節をさらに細かく分けた、意味をもつ言葉としてそれ以上分けられない最小の単位を何というか。', T('単語', 'たんご'), '単語。', near=['文節', '文字'])
    for sent, n, nr, expl in [('空が青い。', 3, ['2', '4'], '空／が／青い（3単語）。'),
                              ('私は毎日本を読む。', 6, ['5', '7'], '私／は／毎日／本／を／読む（6単語）。'),
                              ('妹と公園で遊んだ。', 6, ['5', '7'], '妹／と／公園／で／遊ん／だ（6単語）。「遊んだ」は「遊ん」と「だ」に分かれる。'),
                              ('明日は雨が降るだろう。', 6, ['5', '4'], '明日／は／雨／が／降る／だろう（6単語）。')]:
        q(16, '文法1', '単語の数', f'次の文はいくつの単語に分けられるか。\n{sent}', N(n, ['単語', 'つ', '語']), expl, near=nr)
    q(16, '文法1', '複合語', '「筆箱」「書き表す」のように、二つ以上の単語が結び付いてできた一つの単語を何というか。', T('複合語', 'ふくごうご'), '複合語。', near=['熟語', '単語'])
    q(16, '文法1', '複合語', '「書き表す」は、どのような単語が結び付いた複合語か。次から選ぼう。\nア 名詞＋名詞　イ 動詞＋動詞　ウ 名詞＋形容詞', T('イ'), '書く（動詞）＋表す（動詞）。', near=['ア', 'ウ'])
    q(16, '文法1', '複合語', '「名高い」は、どのような単語が結び付いた複合語か。次から選ぼう。\nア 名詞＋形容詞　イ 動詞＋動詞　ウ 形容詞＋名詞', T('ア'), '名（名詞）＋高い（形容詞）。', near=['イ', 'ウ'])
    q(16, '文法1', '複合語', '次のうち、複合語ではないものを選ぼう。\nア 雨上がり　イ 飛び回る　ウ 美しい　エ 見送る', T('ウ'), '「美しい」は一つの形容詞。ほかは二つの単語が結び付いた複合語。', near=['ア', 'エ'])
    # 文の成分
    q(48, '文法2', '主語・述語', '文の中で「何が（誰が）」にあたる文節を何というか。', T('主語', 'しゅご'), '主語。', near=['述語', '修飾語'])
    q(48, '文法2', '主語・述語', '文の中で「どうする・どんなだ・何だ・ある（いる・ない）」にあたる文節を何というか。', T('述語', 'じゅつご'), '述語。', near=['主語', '修飾語'])
    for sent, subj, pred, nr in [('夜空に　星が　きらきらと　かがやく。', '星が', 'かがやく', ['夜空に', 'きらきらと']),
                                 ('この　かばんは　とても　軽い。', 'かばんは', '軽い', ['この', 'とても']),
                                 ('父も　昔は　サッカー部員だった。', '父も', 'サッカー部員だった', ['昔は', '父']),
                                 ('校庭の　すみに　大きな　木が　ある。', '木が', 'ある', ['すみに', '大きな'])]:
        q(48, '文法2', '主語', f'次の文の主語にあたる文節を書き抜こう。\n{sent}', T(subj), f'主語は「{subj}」。主語は「は」「も」で示されることもある。', near=[x for x in nr if x != subj])
        q(48, '文法2', '述語', f'次の文の述語にあたる文節を書き抜こう。\n{sent}', T(pred), f'述語は「{pred}」。述語はふつう文の終わりにある。', near=[x for x in nr if x != pred][:2])
    q(48, '文法2', '主・述の関係', '「この花は　とても　美しい。」の主・述の関係の型を選ぼう。\nア 何が—どうする　イ 何が—どんなだ　ウ 何が—何だ　エ 何が—ある', T('イ'), '美しい＝どんなだ。', near=['ア', 'ウ'])
    q(48, '文法2', '主・述の関係', '「兄は　高校生だ。」の主・述の関係の型を選ぼう。\nア 何が—どうする　イ 何が—どんなだ　ウ 何が—何だ　エ 何が—ある', T('ウ'), '高校生だ＝何だ。', near=['イ', 'エ'])
    q(48, '文法2', '修飾語', '他の文節をくわしく説明する文節を何というか。', T('修飾語', 'しゅうしょくご'), '修飾語。説明される文節は被修飾語。', near=['被修飾語', '接続語'])
    q(48, '文法2', '修飾語', '体言（名詞）をふくむ文節をくわしくする修飾語を何というか。', T('連体修飾語', 'れんたいしゅうしょくご'), '連体修飾語。用言をくわしくするのは連用修飾語。', near=['連用修飾語'])
    q(48, '文法2', '修飾語', '用言（動詞・形容詞・形容動詞）をふくむ文節をくわしくする修飾語を何というか。', T('連用修飾語', 'れんようしゅうしょくご'), '連用修飾語。', near=['連体修飾語'])
    q(48, '文法2', '用言', '動作・存在・性質・状態などを表し、単独で述語になり、形が変わる言葉（動詞・形容詞・形容動詞）をまとめて何というか。', T('用言', 'ようげん'), '用言。名詞は体言。', near=['体言'])
    q(48, '文法2', '体言', '事物や人の名前を表す名詞のことを、まとめて何というか。', T('体言', 'たいげん'), '体言。', near=['用言'])
    q(49, '文法2', '修飾・被修飾', '「赤い　風船が　ゆっくり　空へ　のぼる。」で、「赤い」が修飾している文節を書き抜こう。', T('風船が'), '赤い→風船が（連体修飾語）。', near=['空へ', 'のぼる'])
    q(49, '文法2', '修飾・被修飾', '「赤い　風船が　ゆっくり　空へ　のぼる。」で、「ゆっくり」が修飾している文節を書き抜こう。', T('のぼる'), 'ゆっくり→のぼる（連用修飾語）。', near=['空へ', '風船が'])
    q(49, '文法2', '修飾・被修飾', '「私は　駅前の　新しい　店で　パンを　買った。」で、「駅前の」が修飾している文節を書き抜こう。', T('店で'), '駅前の→店で。「新しい」も「店で」を修飾している。', near=['新しい', 'パンを'])
    q(50, '文法2', '接続語', '前後の文や文節をつなぎ、理由や条件などを表す文節を何というか。', T('接続語', 'せつぞくご'), '接続語。', near=['独立語', '修飾語'])
    q(50, '文法2', '接続語', '「寒かったので、上着を　着た。」の接続語を書き抜こう。', T('寒かったので', '寒かったので、'), '「寒かったので」が理由を表す接続語。', near=['上着を', '着た'])
    q(50, '文法2', '接続語', '「練習した。だから、試合に　勝てた。」の2文目の接続語を書き抜こう。', T('だから', 'だから、'), '「だから」が前の文とつなぐ接続語。', near=['試合に', '勝てた'])
    q(50, '文法2', '独立語', '他の文節と直接結び付かず、感動・呼びかけ・応答・提示などを表す文節を何というか。', T('独立語', 'どくりつご'), '独立語。', near=['接続語', '主語'])
    q(50, '文法2', '独立語', '「はい、私が　やります。」の独立語を書き抜こう。', T('はい', 'はい、'), '「はい」（応答）が独立語。', near=['私が', 'やります'])
    q(50, '文法2', '独立語', '「夏休み、それは　一年で　いちばん　楽しい　時期だ。」の独立語を書き抜こう。', T('夏休み', '夏休み、'), '「夏休み」は提示の独立語。', near=['それは', '時期だ'])
    q(50, '文法2', '並立の関係', '「ノートと　鉛筆を　買う。」の「ノートと」と「鉛筆を」のように、二つ以上の文節が対等に並ぶ関係を何というか。', T('並立の関係', '並立', 'へいりつのかんけい'), '並立の関係。', near=['補助の関係', '修飾・被修飾の関係'])
    q(50, '文法2', '補助の関係', '「本を　読んで　いる。」の「読んで」と「いる」のように、主な意味を表す文節に、補助的な意味をそえる文節が付く関係を何というか。', T('補助の関係', '補助', 'ほじょのかんけい'), '補助の関係。', near=['並立の関係'])
    q(51, '文法2', '文節の関係', '「荷物が　重くて　大きい。」の「重くて」と「大きい」の関係を選ぼう。\nア 主・述の関係　イ 修飾・被修飾の関係　ウ 並立の関係　エ 補助の関係', T('ウ'), '重くて・大きいは対等に並ぶ並立の関係。', near=['エ', 'イ'])
    q(51, '文法2', '文節の関係', '「窓を　開けて　おく。」の「開けて」と「おく」の関係を選ぼう。\nア 主・述の関係　イ 修飾・被修飾の関係　ウ 並立の関係　エ 補助の関係', T('エ'), '「おく」が補助的な意味をそえる補助の関係。', near=['ウ', 'イ'])
    q(51, '文法2', '文節の関係', '「鳥が　鳴く。」の「鳥が」と「鳴く」の関係を選ぼう。\nア 主・述の関係　イ 修飾・被修飾の関係　ウ 並立の関係　エ 補助の関係', T('ア'), '主語・述語の関係。', near=['イ', 'ウ'])
    q(51, '文法2', '文節の関係', '「静かな　夜。」の「静かな」と「夜」の関係を選ぼう。\nア 主・述の関係　イ 修飾・被修飾の関係　ウ 並立の関係　エ 補助の関係', T('イ'), '静かな→夜（修飾・被修飾）。', near=['ア', 'エ'])
    q(51, '文法2', '連文節', '二つ以上の文節がまとまって、主語や述語などと同じ働きをするものを何というか。', T('連文節', 'れんぶんせつ'), '連文節。主部・述部・修飾部・接続部・独立部という。', near=['文節', '複合語'])
    q(51, '文法2', '連文節', '「赤くて　大きい　りんごが　届いた。」で、主部にあたる部分を書き抜こう。', T('赤くて大きいりんごが', '赤くて　大きい　りんごが', '赤くて 大きい りんごが'), '連文節「赤くて大きいりんごが」が主部。', near=['りんごが', '大きいりんごが'])
    q(51, '文法2', '文の成分', '文の成分を5つすべて書こう（順は自由）。', S(('主語',), ('述語',), ('修飾語',), ('接続語',), ('独立語',)), '主語・述語・修飾語・接続語・独立語。', near=['主語、述語、修飾語、接続語'])
    q(48, '文法2', '主語', '「明日は　図書館に　行こう。」の文に、主語はあるか。「ある」か「ない」で答えよう。', T('ない', 'ありません', '省略されている'), '主語（私は）が省略されている。「明日は」は主語ではなく修飾語。', near=['ある'])
    q(48, '文法2', '主語', '「ぼくだけが　その　答えを　知っていた。」の主語を書き抜こう。', T('ぼくだけが'), '「〜だけが」も主語になる。', near=['ぼく', '答えを'])
    q(48, '文法2', '述語', '「きれいだね、この　景色は。」の述語を書き抜こう。', T('きれいだね', 'きれいだね、'), '倒置。述語「きれいだね」が前に出ている。', near=['景色は', 'この'])
    q(49, '文法2', '修飾語', '「冷たい　水を　ごくごく　飲む。」で、連体修飾語を書き抜こう。', T('冷たい'), '冷たい→水を（体言を修飾）。', near=['ごくごく'])
    q(49, '文法2', '修飾語', '「冷たい　水を　ごくごく　飲む。」で、「飲む」を修飾する文節を二つ書き抜こう（順は自由）。', S(('水を',), ('ごくごく',)), '水を・ごくごく→飲む（連用修飾語）。', near=['ごくごく'])
    q(50, '文法2', '接続語', '「急いだが、バスに　間に合わなかった。」の接続語を書き抜こう。', T('急いだが', '急いだが、'), '「急いだが」は逆接を表す接続語。', near=['バスに'])
    q(50, '文法2', '独立語', '「まあ、なんて　かわいい　子犬だろう。」の独立語を書き抜こう。', T('まあ', 'まあ、'), '「まあ」（感動）が独立語。', near=['なんて', '子犬だろう'])
    q(50, '文法2', '独立語', '「健太、ちょっと　手伝って。」の独立語は、何を表しているか。次から選ぼう。\nア 感動　イ 呼びかけ　ウ 応答　エ 提示', T('イ'), '「健太」は呼びかけの独立語。', near=['ア', 'ウ'])
    q(51, '文法2', '文節の関係', '「父と　母が　出かけた。」の「父と」と「母が」の関係を選ぼう。\nア 主・述の関係　イ 修飾・被修飾の関係　ウ 並立の関係　エ 補助の関係', T('ウ'), '父と母が＝並立の関係。', near=['イ', 'エ'])
    q(51, '文法2', '文節の関係', '「ケーキを　食べて　しまった。」の「食べて」と「しまった」の関係を選ぼう。\nア 主・述の関係　イ 修飾・被修飾の関係　ウ 並立の関係　エ 補助の関係', T('エ'), '「しまった」は補助の働きをする。', near=['ウ', 'イ'])
    q(51, '文法2', '連文節', '「兄は　朝早く　起きて　走った。」で、「起きて　走った」の部分は文の成分として何部か。', T('述部', 'じゅつぶ'), '連文節が述語の働きをするので述部。', near=['主部', '修飾部'])
    q(15, '文法1', '文の数', '次の文章はいくつの文からできているか。\n朝から雨だった。かさを持って家を出た。駅に着くころには晴れていた。', N(3, ['文', 'つ']), '句点「。」で区切られた三つの文。', near=['2', '4'])
    q(14, '文法1', '文節の数', '次の文はいくつの文節に分けられるか。\n私たちは夏休みに海へ行きます。', N(4, ['文節', 'つ']), '私たちは／夏休みに／海へ／行きます（4文節）。', near=['5', '3'])
    return u

def bunpo2():
    u = unit('bunpo2', '単語のいろいろ（品詞）・日本語の音声・方言と共通語', MAJ, {26, 27, 114, 115, 116, 117, 138, 139},
             '2026-10-07 Claude作成。国語ワークp26〜27（日本語の音声）、p114〜117（文法3 単語のいろいろ：自立語と付属語・活用・品詞分類表）、p138〜139（方言と共通語）を写真で確認し、例文をすべて新しく作った。手書きの答えは使っていない。')
